export function Stat({
  label,
  value,
  className,
}: {
  label: string;
  value: number | string;
  className?: string;
}) {
  return (
    <div
      className={`flex flex-col min-h-[60px] gap-1 rounded-md bg-[#f1f5f9] py-2 pe-2 dark:bg-gray-200 ${className}`}
    >
      <div className="text-xl text-end font-bold text-mainBlue dark:text-gray-700">
        {value}
      </div>
      <div className='flex items-center gap-3 '>
        <div className="h-[20px] min-w-[3px] w-[3px] bg-mainBlue rounded-r-sm"/>
        <div className="line-clamp-1 font-medium text-[#112855] dark:text-gray-600">
          {label}
        </div>
      </div>
    </div>
  );
}
